<?php session_start();require_once __DIR__.'/../../src/db.php';if(!($_SESSION['admin']??false)){header('Location:/admin/');exit;}$scene=(int)($_GET['scene']??$_POST['scene']??0);$db=db();if($_SERVER['REQUEST_METHOD']==='POST'){$q=$db->prepare("INSERT INTO hotspots(scene_id,target_scene_id,label,yaw,pitch,type,content) VALUES(?,?,?,?,?,'scene','')");$q->execute([$scene,(int)$_POST['target'],trim($_POST['label']),(float)$_POST['yaw'],(float)$_POST['pitch']]);}$q=$db->prepare("SELECT s.*,p.image FROM tour_scenes s JOIN panoramas p ON p.id=s.panorama_id WHERE s.id=?");$q->execute([$scene]);$s=$q->fetch();if(!$s)exit('Scene not found');$q=$db->prepare("SELECT * FROM tour_scenes WHERE tour_id=? AND id<>? ORDER BY sort_order");$q->execute([$s['tour_id'],$scene]);$targets=$q->fetchAll();$q=$db->prepare("SELECT h.*,ts.title target_title FROM hotspots h LEFT JOIN tour_scenes ts ON ts.id=h.target_scene_id WHERE h.scene_id=?");$q->execute([$scene]);$hs=$q->fetchAll();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/admin.css"></head><body><aside><div class="logo">MINI<span>VR</span></div><a href="/admin/tours.php?edit=<?=$s['tour_id']?>">← Сцены</a></aside><main><header><div><small>SPATIAL LINKS</small><h1>Hotspots</h1></div></header><p style="color:#7f9ca8">Первая версия: yaw/pitch вводятся числом. Следующим шагом редактор будет ставить точку кликом прямо на панораме.</p><form class="editor" method="post"><input type="hidden" name="scene" value="<?=$scene?>"><label>Подпись<input name="label" value="Перейти" required></label><label>Целевая сцена<select name="target"><?php foreach($targets as $t):?><option value="<?=$t['id']?>"><?=htmlspecialchars($t['title']?:'Scene '.$t['id'])?></option><?php endforeach;?></select></label><label>Yaw<input type="number" step=".1" name="yaw" value="0"></label><label>Pitch<input type="number" step=".1" name="pitch" value="0"></label><button class="btn">＋ ДОБАВИТЬ HOTSPOT</button></form><div class="table" style="margin-top:25px"><?php foreach($hs as $h):?><div class="row"><div class="grow"><b><?=htmlspecialchars($h['label'])?></b><small>yaw <?=$h['yaw']?> / pitch <?=$h['pitch']?></small></div><span>→ <?=htmlspecialchars($h['target_title']??'scene')?></span></div><?php endforeach;?></div></main></body></html>